    sale_df = df[sale_mask].copy()

    order_net = sale_df.groupby('Name').agg(
        gross=('Lineitem price', lambda x: (x * sale_df.loc[x.index, 'Lineitem quantity']).sum()),
        discount=('Discount Amount', 'first'),
        country=('Shipping Country', 'first')
    ).reset_index()
    order_net['net_sales'] = order_net['gross'] - order_net['discount'].fillna(0)

    country_aov = order_net.groupby('country').agg(
        total_net=('net_sales', 'sum'),
        order_count=('Name', 'count')
    ).reset_index()
    country_aov['aov'] = country_aov['total_net'] / country_aov['order_count']
    country_aov = country_aov.sort_values('order_count', ascending=False).head(10)

    aov_results = [
        {"name": str(row['country']), "value": round(float(row['aov']), 4)}
        for _, row in country_aov.iterrows()
    ]

    result['segments'].append({
        "segment_column": "Shipping Country",
        "metric_column": "Name",
        "aggregation": "ratio",
        "label": "avg_order_value_net_sales_per_order",
        "results": aov_results
    })

    country_qty = sale_df.groupby('Shipping Country')['Lineitem quantity'].sum().reset_index()
    country_qty = country_qty.sort_values('Lineitem quantity', ascending=False).head(10)
    result['segments'].append({
        "segment_column": "Shipping Country",
        "metric_column": "Lineitem quantity",
        "aggregation": "sum",
        "label": None,
        "results": [
            {"name": str(row['Shipping Country']), "value": float(row['Lineitem quantity'])}
            for _, row in country_qty.iterrows()
        ]
    })

    country_price = sale_df.groupby('Shipping Country')['Lineitem price'].mean().reset_index()
    country_price = country_price.sort_values('Lineitem price', ascending=False).head(10)
    result['segments'].append({
        "segment_column": "Shipping Country",
        "metric_column": "Lineitem price",
        "aggregation": "mean",
        "label": None,
        "results": [
            {"name": str(row['Shipping Country']), "value": round(float(row['Lineitem price']), 4)}
            for _, row in country_price.iterrows()
        ]
    })

    result['assumptions'].append("AOV = net_sales / distinct orders; net_sales = sum(qty * unit_price) - discount (once per order); sale rows + USD only.")
    result['assumptions'].append("Discount Amount taken as first value per order (fill_within_order already applied); NaN discount treated as 0.")
    result['assumptions'].append("Top 10 countries by order count shown for each segment.")
except Exception as e:
    result['assumptions'].append(f"Segmentation error: {str(e)}")

